const wd="/home/axel/LeanAlgebraicGeometry-Horizon/MainProjects/Algebraic-Jacobian-Challenge-Rebuild";
const files=[
"AlgebraicJacobian/Picard/TensorFiniteSubextension.lean",
"AlgebraicJacobian/Picard/FinitePresentationAlgebraFiniteStage.lean",
"AlgebraicJacobian/Picard/PicEtFiniteStageCover.lean",
"AlgebraicJacobian/Picard/CechPicFiniteStage.lean",
"AlgebraicJacobian/Picard/RelPicFiniteStage.lean",
"AlgebraicJacobian/Picard/PicEtAffFiniteStage.lean",
"AlgebraicJacobian/Picard/Pic0FiniteStageDatum.lean"
];
const rs=await Promise.all(files.map(f=>tools.exec_command({cmd:`rg -n "^\\s*(structure|class|def|abbrev|noncomputable def|theorem|lemma|instance|noncomputable instance)\\s+" ${f}`,workdir:wd,yield_time_ms:30000,max_output_tokens:20000})));
for(let i=0;i<rs.length;i++)text(`${files[i]}\n${rs[i].output}`);

const r = await tools.exec_command({
  cmd: "\"$HORIZON_GIT\" ls-tree -r --name-only HEAD | awk '/\\.lock$/ {lock++} /\\.tmp$/ {tmp++} END {print \"lock=\" (lock+0) \" tmp=\" (tmp+0) \" total=\" (lock+tmp+0)}'",
  workdir: "/home/axel/LeanAlgebraicGeometry-Horizon",
  yield_time_ms: 10000,
  max_output_tokens: 10000
});
text(r.output);

const wd="/home/axel/LeanAlgebraicGeometry-Horizon/MainProjects/Algebraic-Jacobian-Challenge-Rebuild";
const specs=[
 ["fpalg","AlgebraicJacobian/Picard/FinitePresentationAlgebraFiniteStage.lean","1,130"],
 ["etale","AlgebraicJacobian/Picard/PicEtFiniteStageCover.lean","1,120"],
 ["cech","AlgebraicJacobian/Picard/CechPicFiniteStage.lean","1,100"],
 ["relpic","AlgebraicJacobian/Picard/RelPicFiniteStage.lean","1,100"],
 ["picet","AlgebraicJacobian/Picard/PicEtAffFiniteStage.lean","1,110"],
 ["tensor1","AlgebraicJacobian/Picard/TensorFiniteSubextension.lean","1,130"],
 ["tensor2","AlgebraicJacobian/Picard/TensorFiniteSubextension.lean","130,230"]
];
const rs=await Promise.all(specs.map(([name,file,range])=>tools.exec_command({cmd:`nl -ba ${file} | sed -n '${range}p'`,workdir:wd,yield_time_ms:30000,max_output_tokens:30000})));for(let i=0;i<rs.length;i++)text(`${specs[i][0]}\n${rs[i].output}`);

const cmds = [
  "sed -n '1,320p' AlgebraicJacobian/Descent/FiniteInAffine.lean",
  "rg -n \"OrbitsInAffineOpen|FiniteInAffine|SemilinearGalAction|translation|translate|mulLeft|leftMul\" AlgebraicJacobian/Descent AlgebraicJacobian -g '*.lean'",
  "rg --files AlgebraicJacobian/Descent | sort",
  "git status --short --untracked-files=all"
];
const rs = await Promise.all(cmds.map(cmd => tools.exec_command({cmd,workdir:"/home/axel/LeanAlgebraicGeometry-Horizon/MainProjects/Algebraic-Jacobian-Challenge-Rebuild",yield_time_ms:10000,max_output_tokens:30000})));
rs.forEach((r,i)=>{text(`RESULT ${i+1}\n${r.output}`); if(r.exit_code!==0) text(`exit ${r.exit_code}`)});

const r = await tools.exec_command({
  cmd: "\"$HORIZON_BIN\" inbox comment I-1913 --body 'Fresh ledger-tree correction: `$HORIZON_GIT ls-tree -r --name-only HEAD` reports 512 tracked `.lock` paths and 40 tracked `.tmp` paths (552 total), not the 1 recorded in the preceding comment. The one-path measurement was therefore scoped incorrectly; the integration filter/cleanup issue remains fully live and has worsened beyond the original 380-path snapshot.' --json",
  workdir: "/home/axel/LeanAlgebraicGeometry-Horizon",
  yield_time_ms: 10000,
  max_output_tokens: 10000
});
text(r.output);

const qs=["finite subextension algebra hom model","finitely presented algebra map descent","finite subextension localization map","base change gluing scheme finite presentation"];
for (const q of qs) {
  const r=await tools.exec_command({cmd:`"$HORIZON_BIN" search "${q}" --json`,workdir:"/home/axel/LeanAlgebraicGeometry-Horizon/MainProjects/Algebraic-Jacobian-Challenge-Rebuild",yield_time_ms:30000,max_output_tokens:12000});
  text(`${q}\n${r.output}`);
}

const qs = [
  "group scheme translate point",
  "GrpObj left multiplication isomorphism",
  "CommGrpObj Scheme multiplication point",
  "irreducible group scheme affine open finite subset"
];
const rs = await Promise.all(qs.map(q => tools.exec_command({cmd:`"$HORIZON_BIN" search "${q}" --json`,workdir:"/home/axel/LeanAlgebraicGeometry-Horizon/MainProjects/Algebraic-Jacobian-Challenge-Rebuild",yield_time_ms:30000,max_output_tokens:12000})));
rs.forEach((r,i)=>{text(`QUERY ${qs[i]}\n${r.output}`); if(r.exit_code!==0) text(`exit ${r.exit_code}`)});

